func checkpointFetchTargetFrom(ctx context.Context, leadRemote string) (string, bool) {
	url, authoritative, err := fetchURLAuthoritative(ctx, FetchURLOptions{LeadReadRemote: leadRemote})
	if err == nil && url != "" {
